/* ════════════════════════════════════════════════════════════════════════════════════════════
   PAGE-PLAN QUEUE (Stage 1) — the per-client months-long working plan: measured questions clustered
   into distinct-job pages, scored, waved (siblings together), stored in the DB (client_pages), and
   EDITABLE here: reorder, move wave, hold/un-hold, remove, merge, rename. Nothing generates from
   here yet (Stage 3 hands rows to the generator). Build/Rebuild is the one priced action (~2p, one
   clustering call) and REPLACES the stored plan — the confirm says so. Holds and near-dup flags are
   always itemised with reasons, never silent (house rule).

   📍 WHERE IT LIVES (2026-10-06): inside Paid Clients. The list's Tools tab renders it with the
   client picker (every client with a baseline — lead-less national clients included); a client's own
   page renders it SCOPED (`scopeAuditId` = that client's baseline, no picker, and the picked client
   remembered for the Tools tab is left alone). The old /page-plan URL redirects to the Tools tab.
   "Build this page" hands off to the generator in the same place (`onHandoff`), or — unscoped — to
   the Tools tab's generator (handoffUrl). Same edge function, same actions, same data.
   ════════════════════════════════════════════════════════════════════════════════════════════ */

interface QaClient { audit_id: string; business_name: string; business_type: string | null }
interface PlanRow {
  id: string; job: string; topic: string; primary_question: string; rationale: string | null;
  lead_id: string | null; baseline_audit_id: string;
  winnability: string | null; score: number | null; score_reasons: string[] | null;
  wave: number; position: number; status: 'planned' | 'held' | 'merged' | 'removed';
  held_reason: string | null; near_dup_of: string | null;
  top_sources: { domain: string; count: number }[] | null;
  /* named_rate is counts ({named, runs} per engine) since 2026-08-28; older rows may carry a plain
     fraction — render both, never crash on either. */
  questions: { question_text: string; named_rate: { chatgpt: unknown; gemini: unknown } | null }[];
}

const namedCell = (v: unknown): string => {
  if (v && typeof v === 'object' && 'named' in (v as object)) {
    const e = v as { named: number; runs: number };
    return `${e.named}/${e.runs}`;
  }
  if (typeof v === 'number') return `${Math.round(v * 100)}%`; // legacy fraction shape
  return '—';
};

/* Gemini-gap tag, derived from the STORED counts (same rule as the lib): named on ChatGPT in ≥half
   of ≥2 runs but not on Gemini. Pages are the Gemini lever (§5: ChatGPT reads directories, Gemini
   reads the client's own site), so these BUILD — the tag just shows the existing ChatGPT strength. */
const engNamed = (v: unknown): boolean => {
  if (!v || typeof v !== 'object' || !('named' in (v as object))) return false;
  const e = v as { named: number; runs: number };
  return e.runs >= 2 && e.named / e.runs >= 0.5;
};
const isGeminiGapRow = (r: PlanRow): boolean =>
  r.status === 'planned' && r.questions.some((q) => engNamed(q.named_rate?.chatgpt) && !engNamed(q.named_rate?.gemini));

/* One row's verdict as a printable label — the same derivations the screen uses (held wording for
   the kind, stored counts for the gap), so the PDF can never disagree with the screen. */
const printLabelFor = (r: PlanRow): { kind: PlanLabelKind; label: string } => {
  if (r.status === 'held') {
    const hr = r.held_reason ?? '';
    if (hr.includes('market locked')) return { kind: 'locked', label: 'Hold — market locked' };
    if (hr.includes('official bodies')) return { kind: 'authority', label: 'Hold — authority sources' };
    return { kind: 'defend', label: 'Defend — already named' };
  }
  return isGeminiGapRow(r) ? { kind: 'gap', label: 'Build — Gemini gap' } : { kind: 'build', label: 'Build' };
};

/* Winnability badges in the AUDIT'S vocabulary (classifyWinnability verdicts, majority across the
   runs) — so the queue's label matches what the audit page shows for the same question. */
const WINN_STYLE: Record<string, string> = {
  open: 'border-emerald-500/40 text-emerald-600 dark:text-emerald-500',
  contested: 'border-sky-500/40 text-sky-600 dark:text-sky-400',
  no_local_race: 'border-violet-500/40 text-violet-600 dark:text-violet-400',
  named: 'border-emerald-500/40 text-emerald-600 dark:text-emerald-500',
  'Gemini gap': 'border-amber-500/40 text-amber-600 dark:text-amber-500',
  'partly named': 'border-border text-muted-foreground',
  locked: 'border-red-500/40 text-red-600 dark:text-red-500',
  unmeasured: 'border-border text-muted-foreground',
};

/* ⛔ Q&A / INFORMATIONAL — DERIVED FROM `winnability`, NOT FROM `page_type`. DISPLAY ONLY.
   page_type looks like the field for this and is NOT: plan_build inserts the literal "qa" on EVERY
   row, town pages included (page-generator/index.ts:470), which is why pagePlanHandoff.ts already
   refuses to read it. The plan also never stores the report's "informational" label — it grades with
   classifyWinnability's vocabulary, where the equivalent verdict is `no_local_race`: "No local firms
   named — AI gives generic advice, so there is no local race to win here" (auditReport.ts:669). That
   is the informational question, and it is the one per-row field that marks one.
   ⚠️ Adds nothing to the decision: the pill is rendered beside the existing status pill and no
   score, wave, hold or stored value reads it. */
const isQaRow = (r: PlanRow): boolean => r.winnability === 'no_local_race';

/* The small status pill, DISPLAY ONLY: a bare "named" pill on a BUILDING card contradicts the
   BUILD chip beside it (Paul, 2026-08-28). On builds the pill reflects the build state — the gap
   builds read "Gemini gap", a rare non-gap named-label build reads "partly named" — while "named"
   stays exactly right on held/defend cards. No decision, score or reason text changes here. */
const pillFor = (r: PlanRow): string | null => {
  if (!r.winnability) return null;
  if (r.status !== 'planned') return r.winnability.replace(/_/g, ' ');
  if (isGeminiGapRow(r)) return 'Gemini gap';
  if (r.winnability === 'named') return 'partly named';
  return r.winnability.replace(/_/g, ' ');
};

export function PagePlanTool({ scopeAuditId, onHandoff }: {
  /** A client's own page: their baseline audit. Omitted = the Tools tab, with the picker. */
  scopeAuditId?: string;
  /** Where "Build this page" goes when the generator sits beside this tool (a client's page). */
  onHandoff?: (target: HandoffTarget) => void;
} = {}) {
  const { toast } = useToast();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [clients, setClients] = useState<QaClient[]>([]);
  const [storedClientId, setStoredClientId] = usePersistedState<string>('pageplan-client', '', { tier: 'both', scope: user?.id });
  const clientId = scopeAuditId ?? storedClientId;
  /* Scoped: the client is fixed by the page, and the Tools tab's remembered pick is not touched. */
  const setClientId = (id: string) => { if (!scopeAuditId) setStoredClientId(id); };
  const [rows, setRows] = useState<PlanRow[]>([]);
  const [busy, setBusy] = useState(false);
  const [building, setBuilding] = useState(false);
  const [tablesMissing, setTablesMissing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [open, setOpen] = useState<Record<string, boolean>>({});
  const [editing, setEditing] = useState<{ id: string; job: string } | null>(null);
  const [mergeFrom, setMergeFrom] = useState<string>('');
  /* Client vs Internal for the PRINTED document — same leak-safe rule as the audit report:
     default CLIENT, reset to Client on every client switch, so the internal PDF is always a
     conscious two-step choice and a forgotten toggle can never hand a client the internal notes. */
  const [showInternal, setShowInternal] = useState(false);

  useEffect(() => {
    void (async () => {
      const { data: res } = await supabase.functions.invoke('page-generator', { body: { action: 'qa_clients' } });
      if (res?.ok) setClients(res.clients ?? []);
    })();
  }, []);
  /* A client's page can change its scope without unmounting (another client opened): reload. */
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { if (scopeAuditId) void load(scopeAuditId); }, [scopeAuditId]);

  const load = async (auditId: string) => {
    setClientId(auditId);
    setRows([]); setError(null); setTablesMissing(false); setMergeFrom('');
    setShowInternal(false); // never carry an internal choice across clients (leak-safe default)
    if (!auditId) return;
    setBusy(true);
    try {
      const { data: res, error: err } = await supabase.functions.invoke('page-generator', { body: { action: 'plan_get', audit_id: auditId } });
      if (err) throw new Error(err.message);
      if (!res?.ok) {
        if (res?.error === 'plan_tables_missing') { setTablesMissing(true); return; }
        throw new Error(res?.error ?? 'load failed');
      }
      setRows(res.pages ?? []);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'load failed');
    } finally {
      setBusy(false);
    }
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { if (!scopeAuditId && clientId) void load(clientId); }, []);

  const build = async () => {
    if (!clientId) return;
    const replaces = rows.length > 0 ? ' This REPLACES the current plan, including your edits.' : '';
    if (!window.confirm(`Build the page plan from the measured questions? One AI clustering call (~2p).${replaces}`)) return;
    setBuilding(true); setError(null);
    try {
      const { data: res, error: err } = await supabase.functions.invoke('page-generator', { body: { action: 'plan_build', audit_id: clientId } });
      if (err) throw new Error(err.message);
      if (!res?.ok) {
        if (res?.error === 'plan_tables_missing') { setTablesMissing(true); return; }
        if (res?.error === 'no_credits') { setError('AI credits need topping up — the plan builds the moment credits land.'); return; }
        throw new Error(res?.error ?? 'build failed');
      }
      if (res.partitionOk === false) toast({ title: 'Clustering fell back to one-page-per-question', description: String((res.problems ?? []).slice(0, 2).join('; ')), variant: 'destructive' });
      await load(clientId);
      toast({ title: `Plan built — ${res.built} pages from ${res.questionCount} questions` });
    } catch (e) {
      setError(e instanceof Error ? e.message : 'build failed');
    } finally {
      setBuilding(false);
    }
  };

  const update = async (pageId: string, body: Record<string, unknown>, reload = true) => {
    const { data: res, error: err } = await supabase.functions.invoke('page-generator', { body: { action: 'plan_update', page_id: pageId, ...body } });
    if (err || !res?.ok) { toast({ title: 'Update failed', description: err?.message ?? res?.error, variant: 'destructive' }); return false; }
    if (reload && clientId) await load(clientId);
    return true;
  };

  const swap = async (a: PlanRow, b: PlanRow) => {
    await update(a.id, { set: { position: b.position } }, false);
    await update(b.id, { set: { position: a.position } }, true);
  };

  /* ── "BUILD THIS PAGE" — the plan→generator handoff. MODE IS DERIVED, never asked (and never
     read from the row's page_type, which is hardcoded 'qa'): a lead client whose verbatim question
     sits in a real generator service page → Service+Area seeded with that page's key; everything
     else → Q&A seeded with the question. The generator plan read is FREE (no AI). NO auto-generate,
     NO auto-publish — the seed only selects and highlights; a genuine resolution failure is said
     out loud and navigates nowhere (never the wrong page). */
  const [handingOff, setHandingOff] = useState('');
  const buildThis = async (r: PlanRow) => {
    setHandingOff(r.id);
    try {
      let genPages: { key: string; queries: string[] }[] | null = null;
      let genExcluded: { question: string; reason: string }[] | null = null;
      if (r.lead_id) {
        const { data: res, error: err } = await supabase.functions.invoke('page-generator', { body: { action: 'plan', lead_id: r.lead_id } });
        if (!err && res?.ok) { genPages = res.plan?.pages ?? []; genExcluded = res.plan?.excluded ?? []; }
        // err or !ok leaves genPages null → resolveHandoff returns 'unresolved' (honest, no guess)
      }
      const target = resolveHandoff(
        { lead_id: r.lead_id, baseline_audit_id: r.baseline_audit_id, primary_question: r.primary_question, questions: r.questions.map((q) => q.question_text) },
        genPages, genExcluded,
      );
      if (target.mode === 'unresolved') {
        toast({ title: "Couldn't match this row to a page", description: target.reason, variant: 'destructive' });
        return;
      }
      if (target.mode === 'qa' && target.note) toast({ title: 'Opening as a Q&A article', description: target.note });
      if (onHandoff) onHandoff(target); else navigate(handoffUrl(target)!);
    } catch (e) {
      toast({ title: "Couldn't match this row to a page", description: e instanceof Error ? e.message : 'Open the page generator manually.', variant: 'destructive' });
    } finally {
      setHandingOff('');
    }
  };

  /* Assemble the printable document from the SAME rows the screen renders, and print via the SAME
     print-to-PDF path as the audit report. Prints whichever view the toggle shows. */
  const downloadPdf = () => {
    const client = clients.find((c) => c.audit_id === clientId);
    const activeRows = rows.filter((r) => r.status === 'planned' || r.status === 'held')
      .sort((a, b) => a.wave - b.wave || a.position - b.position);
    const byWave = new Map<number, PagePlanReportItem[]>();
    for (const r of activeRows) {
      const { kind, label } = printLabelFor(r);
      const item: PagePlanReportItem = {
        job: r.job, topic: r.topic, labelKind: kind, label,
        winnability: r.winnability,
        questions: r.questions.map((q) => ({
          text: q.question_text, chatgpt: namedCell(q.named_rate?.chatgpt), gemini: namedCell(q.named_rate?.gemini),
        })),
        sources: r.top_sources ?? [],
        heldReason: r.held_reason,
        score: r.score, rationale: r.rationale, scoreReasons: r.score_reasons ?? [],
      };
      (byWave.get(r.wave) ?? byWave.set(r.wave, []).get(r.wave)!).push(item);
    }
    const html = renderPagePlanHtml({
      businessName: client?.business_name ?? 'Client',
      businessType: client?.business_type ?? null,
      generatedAtLabel: new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }),
      internal: showInternal,
      waves: [...byWave.entries()].sort((a, b) => a[0] - b[0]).map(([wave, items]) => ({ wave, items })),
    });
    downloadHtmlDocAsPdf(html, client?.business_name ?? 'Client', 'Page-Plan');
  };

  const active = rows.filter((r) => r.status === 'planned' || r.status === 'held');
  const waves = [...new Set(active.map((r) => r.wave))].sort((a, b) => a - b);
  const gone = rows.filter((r) => r.status === 'merged' || r.status === 'removed');
  const jobOf = (id: string | null) => rows.find((r) => r.id === id)?.job ?? null;

  const row = (r: PlanRow, siblings: PlanRow[]) => {
    const idx = siblings.findIndex((s) => s.id === r.id);
    return (
      <div key={r.id} data-status={r.status} className={cn('space-y-1.5 rounded-xl border p-3', r.status === 'held' ? cn('border-amber-500/30 bg-amber-500/[0.06]', EDGE.amber) : isGeminiGapRow(r) ? cn('border-border/60 bg-muted/20', EDGE.purple) : cn('border-border/60 bg-muted/20', EDGE.blue))}>
        <div className="flex flex-wrap items-center gap-2">
          <button className="text-muted-foreground" onClick={() => setOpen((o) => ({ ...o, [r.id]: !o[r.id] }))}>
            {open[r.id] ? <ChevronDown className="h-3.5 w-3.5" /> : <ChevronRight className="h-3.5 w-3.5" />}
          </button>
          {editing?.id === r.id ? (
            <>
              <Input className="h-7 w-full text-sm sm:w-64" value={editing.job} onChange={(e) => setEditing({ id: r.id, job: e.target.value })} />
              <Button size="sm" className="h-7" onClick={async () => { if (await update(r.id, { set: { job: editing.job } })) setEditing(null); }}>Save</Button>
              <Button size="sm" variant="ghost" className="h-7" onClick={() => setEditing(null)}>Cancel</Button>
            </>
          ) : (
            <span className="font-medium text-sm cursor-pointer" title="Click to rename" onClick={() => setEditing({ id: r.id, job: r.job })}>{r.job}</span>
          )}
          <Badge variant="outline" className="text-[10px] font-normal">{r.topic}</Badge>
          {pillFor(r) && <Badge variant="outline" className={`text-[10px] ${WINN_STYLE[pillFor(r)!] ?? WINN_STYLE[r.winnability ?? ''] ?? ''}`}>{pillFor(r)}</Badge>}
          {/* Q&A marker — same Badge component and the same class string the "no local race"
              pill already uses, so it introduces no new colour or shape. */}
          {isQaRow(r) && (
            <Badge variant="outline" className={`text-[10px] ${WINN_STYLE.no_local_race}`}>Q&amp;A</Badge>
          )}
          {isGeminiGapRow(r) && (
            <Badge variant="outline" className="text-[10px] border-amber-500/40 text-amber-600 dark:text-amber-500">
              Gemini gap — already strong on ChatGPT
            </Badge>
          )}
          <Badge variant="outline" className="text-[10px] font-normal">score {r.score ?? '—'}</Badge>
          {r.questions.length > 1 && <Badge variant="outline" className="text-[10px] font-normal">{r.questions.length} variants merged</Badge>}
          {r.near_dup_of && (
            <span className="flex items-center gap-1 text-[10px] text-amber-600"><AlertTriangle className="h-3 w-3" /> near-duplicate of “{jobOf(r.near_dup_of) ?? 'another page'}”</span>
          )}
          <span className="flex w-full flex-wrap items-center gap-1 sm:ml-auto sm:w-auto">
            {r.status === 'planned' && (
              <Button size="sm" variant="outline" className="h-7 px-2 text-xs" disabled={handingOff === r.id}
                title="Open the page generator pre-filled for this page (nothing generates until you press Generate there)"
                onClick={() => buildThis(r)}>
                {handingOff === r.id ? <Loader2 className="mr-1 h-3 w-3 animate-spin" /> : <Hammer className="mr-1 h-3 w-3" />}
                Build this page
              </Button>
            )}
            <Button size="sm" variant="ghost" className="h-7 px-1.5" disabled={idx <= 0} onClick={() => swap(r, siblings[idx - 1])} title="Move up"><ArrowUp className="h-3.5 w-3.5" /></Button>
            <Button size="sm" variant="ghost" className="h-7 px-1.5" disabled={idx >= siblings.length - 1} onClick={() => swap(r, siblings[idx + 1])} title="Move down"><ArrowDown className="h-3.5 w-3.5" /></Button>
            <Button size="sm" variant="ghost" className="h-7 px-2 text-xs" title={`Move this page to wave ${r.wave === 1 ? 2 : 1}`} onClick={() => update(r.id, { set: { wave: r.wave === 1 ? 2 : 1 } })}>Move to wave {r.wave === 1 ? 2 : 1}</Button>
            {r.status === 'held'
              ? <Button size="sm" variant="ghost" className="h-7 px-1.5" title="Un-hold" onClick={() => update(r.id, { set: { status: 'planned' } })}><Play className="h-3.5 w-3.5" /></Button>
              : <Button size="sm" variant="ghost" className="h-7 px-1.5" title="Hold" onClick={() => update(r.id, { set: { status: 'held', held_reason: 'held by operator' } })}><Pause className="h-3.5 w-3.5" /></Button>}
            <Button size="sm" variant="ghost" className="h-7 px-1.5" title="Merge into another page" onClick={() => setMergeFrom(mergeFrom === r.id ? '' : r.id)}><GitMerge className="h-3.5 w-3.5" /></Button>
            <Button size="sm" variant="ghost" className="h-7 px-1.5 text-destructive" title="Remove" onClick={() => update(r.id, { set: { status: 'removed' } })}><Trash2 className="h-3.5 w-3.5" /></Button>
          </span>
        </div>
        <p className="text-xs text-muted-foreground">{r.primary_question}</p>
        {(r.top_sources?.length ?? 0) > 0 && (
          <p className="text-xs">
            <span className="text-muted-foreground">engines currently read:</span>{' '}
            {r.top_sources!.map((s) => s.domain).join(', ')}
            <span className="text-muted-foreground"> — where to get listed</span>
          </p>
        )}
        {r.status === 'held' && r.held_reason && <p className="text-xs text-amber-600 dark:text-amber-500">held: {r.held_reason}</p>}
        {mergeFrom === r.id && (
          <div className="flex flex-wrap items-center gap-2 text-xs">
            <span className="text-muted-foreground">Merge “{r.job}” into:</span>
            <Select onValueChange={async (target) => { setMergeFrom(''); await update(r.id, { merge_into: target }); }}>
              <SelectTrigger className="h-7 w-full text-xs sm:w-72"><SelectValue placeholder="pick the page that keeps the job…" /></SelectTrigger>
              <SelectContent>
                {active.filter((x) => x.id !== r.id).map((x) => <SelectItem key={x.id} value={x.id}>{x.job}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        )}
        {open[r.id] && (
          <div className="rounded border border-border/40 bg-muted/30 p-2 space-y-1 text-xs">
            {r.rationale && <p><span className="text-muted-foreground">Why grouped this way:</span> {r.rationale}</p>}
            {(r.score_reasons ?? []).map((s, i) => <p key={i} className="text-muted-foreground">· {s}</p>)}
            {(r.top_sources?.length ?? 0) > 0 && (
              <p><span className="text-muted-foreground">Cited sources (times cited):</span>{' '}
                {r.top_sources!.map((s) => `${s.domain} (${s.count})`).join(' · ')}</p>
            )}
            <p className="font-medium text-muted-foreground pt-1">Questions this page answers (named in N of M runs — ChatGPT / Gemini):</p>
            {r.questions.map((q) => (
              <p key={q.question_text}>“{q.question_text}” <span className="text-muted-foreground">— ChatGPT {namedCell(q.named_rate?.chatgpt)} / Gemini {namedCell(q.named_rate?.gemini)}</span></p>
            ))}
          </div>
        )}
      </div>
    );
  };

  const heldCount = active.filter((r) => r.status === 'held').length;
  const scopedName = scopeAuditId ? clients.find((c) => c.audit_id === scopeAuditId)?.business_name : null;

  return (
    <div className="space-y-5" data-testid="page-plan-tool">
      <p className="text-sm text-muted-foreground">
        Measured questions clustered into distinct-job pages, scored by the evidence, released in
        waves — siblings publish together. Edit freely; nothing is built from here yet.
      </p>

      {/* The controls row: the client (picker on the Tools tab, fixed on a client's page), the one
          priced action, and the printable plan. */}
      <div className="flex flex-wrap items-center gap-2">
        {scopeAuditId
          ? <span className="text-sm font-semibold">{scopedName ?? 'This client'}{active.length > 0 && <span className="ml-2 font-normal text-muted-foreground">{active.length} page{active.length === 1 ? '' : 's'}{heldCount ? ` · ${heldCount} held` : ''}</span>}</span>
          : <Select value={clientId} onValueChange={load}>
              <SelectTrigger className="w-full sm:w-72" aria-label="Client"><SelectValue placeholder="Pick a client with a baseline…" /></SelectTrigger>
              <SelectContent>
                {clients.map((c) => <SelectItem key={c.audit_id} value={c.audit_id}>{c.business_name}{c.business_type ? ` — ${c.business_type}` : ''}</SelectItem>)}
              </SelectContent>
            </Select>}
        {clientId && (
          <Button size="sm" disabled={building} onClick={build}>
            {building ? <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" /> : <Sparkles className="mr-1.5 h-3.5 w-3.5" />}
            {rows.length ? 'Rebuild plan · ~2p' : 'Build plan · ~2p'}
          </Button>
        )}
        {busy && <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />}
        {active.length > 0 && (
          <span className="flex flex-wrap items-center gap-2 sm:ml-auto">
            {/* Same Client/Internal toggle semantics as the audit report: Client is the default,
                Download prints whichever view is selected. */}
            <span className="inline-flex rounded-full bg-muted/70 p-0.5 text-xs ring-1 ring-inset ring-border/50" role="group" aria-label="Report view">
              <button
                type="button" aria-pressed={!showInternal}
                className={cn('h-7 rounded-full px-3 font-semibold transition-colors', !showInternal ? 'bg-card text-foreground shadow-sm ring-1 ring-border/60' : 'text-muted-foreground hover:text-foreground')}
                onClick={() => setShowInternal(false)}
              >Client</button>
              <button
                type="button" aria-pressed={showInternal}
                className={cn('h-7 rounded-full px-3 font-semibold transition-colors', showInternal ? 'bg-amber-500 text-white shadow-sm' : 'text-muted-foreground hover:text-foreground')}
                onClick={() => setShowInternal(true)}
              >Internal</button>
            </span>
            <Button size="sm" variant="outline" onClick={downloadPdf}>
              <FileDown className="mr-1.5 h-3.5 w-3.5" /> Download PDF{showInternal ? ' (internal)' : ''}
            </Button>
          </span>
        )}
      </div>

      {tablesMissing && (
        <Callout tone="amber" icon={Database} title="The plan schema isn't in place yet">
          A table or one of its columns is missing — run
          <code className="mx-1">supabase/migrations/20260828130000_page_plan_reconcile.sql</code>
          in the Supabase SQL editor (it's idempotent and also covers a fresh database after the
          base migration), then press Build.
        </Callout>
      )}
      {error && <Callout tone="red" icon={AlertCircle} title="Something went wrong">{error}</Callout>}

      {waves.map((w) => {
        const members = active.filter((r) => r.wave === w).sort((a, b) => a.position - b.position);
        const held = members.filter((m) => m.status === 'held').length;
        return (
          <SubSection key={w} tone={w === 1 ? 'blue' : 'purple'} icon={Layers} title={`Wave ${w}`}
            hint={`${members.length} page${members.length === 1 ? '' : 's'}${held ? ` · ${held} held` : ''}`}>
            <div className="space-y-2">{members.map((r) => row(r, members))}</div>
          </SubSection>
        );
      })}

      {gone.length > 0 && (
        <SubSection tone="grey" icon={Archive} title="Merged / removed" hint="kept for the record">
          <div className="space-y-1 text-xs text-muted-foreground">
            {gone.map((r) => (
              <p key={r.id}>“{r.job}” — {r.status}{r.near_dup_of && r.status === 'merged' ? ` into “${jobOf(r.near_dup_of) ?? '?'}”` : ''}
                <Button size="sm" variant="ghost" className="ml-1 h-6 px-2 text-xs" onClick={() => update(r.id, { set: { status: 'planned' } })}>restore</Button>
              </p>
            ))}
          </div>
        </SubSection>
      )}

      {clientId && !busy && !tablesMissing && rows.length === 0 && !error && (
        <Empty icon={Layers}>No plan yet for this client — press Build.</Empty>
      )}
      {!clientId && !scopeAuditId && <Empty icon={Layers}>Pick a client with a baseline to see their page plan.</Empty>}
    </div>
  );
}
